Every refinement widget instance should be an EventEmitter and so we would be able to:

``` js
var categories =   instantsearch.widgets.menu({
  container: '#categories',
  facetName: 'categories',
  limit: 10,
  rootClass: 'list-unstyled',
  template: require('./templates/category.html')
});

categories.on('refine', function(newValue, previousValue) {
  // do whatever you want here, like scrolling to some specific place or top.
});

search.addWidget(categories);
```

